#include "ui/SystemScreenShell.hpp"
#include <algorithm>
namespace elysium::ui {bool SystemScreenShell::publish(DomainViewModel v){std::sort(v.rows.begin(),v.rows.end(),[](auto&a,auto&b){return a.stableId<b.stableId;});if(v.domain==ScreenDomain::Map&&!v.chartedOnly)return false;if(v.domain==ScreenDomain::PowerLogistics&&!v.localNetworkOnly)return false;if(v.domain==ScreenDomain::StandingFile&&!v.readOnlyLedger)return false;views_[v.domain]=std::move(v);return true;}const DomainViewModel*SystemScreenShell::view(ScreenDomain d)const{auto i=views_.find(d);return i==views_.end()?nullptr:&i->second;}bool SystemScreenShell::restoreNavigation(ScreenNavigationState n){if(!views_.contains(n.active))return false;nav_=n;return true;}ScreenCommandIntent SystemScreenShell::command(ScreenCommandIntent i)const{if(!i.stableId||!i.targetStableId||!views_.contains(i.domain))return {};return i;}}
